insert into public.brands (code, name, tagline, description, market, primary_color, color, palette, voice, key_messages, funnel_steps, status, workspace_id, id, created_at, updated_at) values ('SAVA', 'SAVA META', 'Play the Unknown. Build the Unknown.', 'Thương hiệu SAVA META — Game Studio & Publishing: xây tệp Game Audience (B2C) và mở cơ hội hợp tác Publishing với Studio/Creator (B2B) qua Game Chapter / Road to Global.', 'Việt Nam', '#066DBD', '#066DBD', '["#066DBD","#0B2A4A","#F5A623","#FFFFFF"]'::jsonb, 'Tiên phong, bản lĩnh, gần gũi với cộng đồng game thủ và giới làm game.', '["PLAY THE UNKNOWN — chơi và khám phá điều chưa biết","BUILD THE UNKNOWN — đưa game Việt ra thị trường toàn cầu","CREATE THE UNKNOWN — cộng đồng sáng tạo game"]'::jsonb, '["Reach","Follow","Participation","Lead","Application"]'::jsonb, 'active', 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', 'ecdb9029-1a4c-4a7b-92f2-f98d6089c532', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00');
insert into public.brands (code, name, tagline, description, market, primary_color, color, palette, voice, key_messages, funnel_steps, status, workspace_id, id, created_at, updated_at) values ('LUMUS', 'Lumus AI', 'AI cho công việc hiệu quả hơn.', 'Lumus AI — sản phẩm AI hỗ trợ productivity và quản lý công việc; funnel B2C từ Reach tới Paid User, kênh B2B (LinkedIn, B2B Event, ads B2B) tách theo segment.', 'Việt Nam (B2C) + thị trường nói tiếng Anh (B2B, LinkedIn 100% English)', '#6C4CF1', '#6C4CF1', '["#6C4CF1","#1E1B4B","#38BDF8","#FFFFFF"]'::jsonb, 'Chuyên môn, rõ ràng, hướng tới hiệu quả đo được.', '["AI hỗ trợ quản lý công việc và năng suất cá nhân","Bắt đầu miễn phí, nâng cấp khi thấy giá trị","Nội dung chuyên môn AI/productivity từ KOL Expert"]'::jsonb, '["Reach","Visit","Signup","First","Paid"]'::jsonb, 'active', 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', 'c21ebdb3-66d5-4217-97ac-3765023c266c', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00');
