insert into public.campaigns (brand_id, segment, name, status, start_date, end_date, owner_id, budget_ceiling_amount, budget_ceiling_currency, audiences, insights, big_idea, key_message, kv_direction, risk_note, custom_fields, workspace_id, id, created_at, updated_at, objectives) values ('ecdb9029-1a4c-4a7b-92f2-f98d6089c532', 'b2c', 'CAMP 01 — PLAY THE UNKNOWN', 'planning', '2026-10-01', '2026-11-30', null, 51539000, 'VND', '[{"name":"Game Audience — người chơi trẻ quan tâm Game","description":"Tiếp cận qua nội dung văn hóa game và ký ức game thủ."}]'::jsonb, 'Nội dung ký ức game (Game Cũ) kéo tương tác tự nhiên tốt (theo file IMC).', 'PLAY THE UNKNOWN — Dấn bước tiên phong.', 'Chơi điều chưa biết cùng SAVA META.', 'Nội dung conversation + livestream hỏi đáp + thử thách ký ức game.', 'Ngân sách Ads phục vụ đồng thời Follower Growth và Submit câu hỏi, chưa chia riêng hai mục tiêu (ghi chú file IMC).', '{"business_unit_id":"Publishing","product":"Game Chapter","why":"Xây dựng tệp khách hàng, mở phễu: tập hợp đúng Game Audience bằng conversation, ký ức và trải nghiệm chung quanh Game.","business_goal":"Đạt >=6.300 lượt theo dõi mới và 200–300 câu hỏi hợp lệ cho Hỏi Ngay – Đáp Thật #02 (số từ file IMC).","marketing_goal":"Brand Content/Game Culture + HNĐT #02 + Game Cũ - Chuyện Cũ trên Meta Ads, Fanpage, PR GameK và Seeding.","desired_outcome":"Phễu B2C SAVA META: Reach -> Follow -> Participation.","lessons":""}'::jsonb, 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', '30c93f15-420f-4c3f-806c-904286d9751c', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00', 'Xây dựng tệp khách hàng, mở phễu: tập hợp đúng Game Audience bằng conversation, ký ức và trải nghiệm chung quanh Game.');
insert into public.campaigns (brand_id, segment, name, status, start_date, end_date, owner_id, budget_ceiling_amount, budget_ceiling_currency, audiences, insights, big_idea, key_message, kv_direction, risk_note, custom_fields, workspace_id, id, created_at, updated_at, objectives) values ('ecdb9029-1a4c-4a7b-92f2-f98d6089c532', 'b2b', 'BUILD THE UNKNOWN — Game Chapter (Camp 2)', 'planning', '2026-11-01', '2027-01-31', null, 154200000, 'VND', '[{"name":"Studio / Indie Developer / Game Creator","description":"Có project thật, quan tâm Publishing và thị trường toàn cầu."}]'::jsonb, 'Contact Leads phải khử trùng, có quyền liên hệ phù hợp; không mặc định 200 leads đều đủ điều kiện RTG (ghi chú file IMC).', 'BUILD THE UNKNOWN — Bản lĩnh mở lối toàn cầu.', 'Đưa game Việt ra thị trường toàn cầu cùng SAVA Publishing.', 'PR CafeF/CafeBiz + nội dung giáo dục Road to Global + seeding cộng đồng indie developer.', 'Market Test Fund 10.000 USD quản lý riêng, không cộng vào ngân sách campaign này.', '{"business_unit_id":"Publishing","product":"Road to Global","why":"Sàng lọc cơ hội kinh doanh, chuyển đổi phễu: đưa Studio/Creator có Project thật vào quy trình đánh giá, Market Test và mở cơ hội hợp tác Publishing.","business_goal":"200 Contact Leads mới, 40 RTG Applications, 3 Market Tests, 1 Winner, 3–5 Publishing Opportunities (số từ file IMC).","marketing_goal":"Studio Outreach x Gameforum + Road to Global (Announcement -> Education -> Submission) + Qualification & Pitch.","desired_outcome":"Phễu B2B SAVA META: Lead -> Application -> Market Test.","lessons":""}'::jsonb, 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', '20ef0c63-2ce4-42bf-9d7a-775bd15861aa', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00', 'Sàng lọc cơ hội kinh doanh, chuyển đổi phễu: đưa Studio/Creator có Project thật vào quy trình đánh giá, Market Test và mở cơ hội hợp tác Publishing.');
insert into public.campaigns (brand_id, segment, name, status, start_date, end_date, owner_id, budget_ceiling_amount, budget_ceiling_currency, audiences, insights, big_idea, key_message, kv_direction, risk_note, custom_fields, workspace_id, id, created_at, updated_at, objectives) values ('ecdb9029-1a4c-4a7b-92f2-f98d6089c532', 'b2c', 'CAMP 03 — CREATE THE UNKNOWN', 'planning', '2027-02-01', '2027-03-31', null, 49349500, 'VND', '[{"name":"Game Audience / Future Builder","description":"Người chơi trẻ muốn thử sáng tạo Game Idea đầu tiên."}]'::jsonb, 'Game Idea Challenge không yêu cầu biết Code/Prototype — hạ rào cản sáng tạo để nhận diện Creator Signal (theo file IMC).', 'CREATE THE UNKNOWN — Tự do kiến tạo.', 'Từ người chơi thành người sáng tạo cùng SAVA META.', 'Livestream HNĐT #03 + thử thách sáng tạo Bé SAVA bằng AI.', '', '{"business_unit_id":"Publishing","product":"Game Chapter","why":"Mở rộng tệp Future Builder, nuôi dưỡng phễu: chuyển Game Audience từ quan tâm sang hành động sáng tạo, qua đó nhận diện những Creator/Game Maker Signal tiềm năng.","business_goal":"New Follows 1.500–1.700; HNĐT #03: 140–160 câu hỏi hợp lệ; SAVA Game Idea Challenge: >=120 Game Idea hợp lệ (số từ file IMC).","marketing_goal":"HNĐT #03 (Paid Ads + PR CafeBiz + Rewards) + SAVA Game Idea Challenge (Paid Ads + Seeding + PR GameK + Rewards).","desired_outcome":"Phễu B2C SAVA META: Follow -> Participation -> Creator Signal.","lessons":""}'::jsonb, 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', '2d8eb288-879e-4bf6-b12d-d21b8ad1506d', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00', 'Mở rộng tệp Future Builder, nuôi dưỡng phễu: chuyển Game Audience từ quan tâm sang hành động sáng tạo, qua đó nhận diện những Creator/Game Maker Signal tiềm năng.');
insert into public.phases (brand_id, name, start_month, end_month, objective, uplift_percent_per_month, note, workspace_id, id, created_at, updated_at) values ('c21ebdb3-66d5-4217-97ac-3765023c266c', 'Preparation', '2027-01', '2027-02', 'Chuẩn bị nền tảng: dựng kênh owned, chốt benchmark và lịch booking KOL/Paid đợt đầu.', 0, 'Objective điền tạm cho bản bấm thử — file nguồn chỉ ghi khoảng tháng T1–T2 và 15% operating budget cho GĐ1.', 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', '30003c16-08e5-4c1d-8e63-57f14842f869', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00');
insert into public.phases (brand_id, name, start_month, end_month, objective, uplift_percent_per_month, note, workspace_id, id, created_at, updated_at) values ('c21ebdb3-66d5-4217-97ac-3765023c266c', 'Test & Validate', '2027-03', '2027-05', 'Kiểm chứng: chạy wave Paid T3–T5 cùng KOL, đo tỉ lệ chuyển đổi thực tế so với benchmark giả định.', 5, 'Objective điền tạm — căn cứ ghi chú file nguồn "Ưu tiên 2 wave: T3–T5 và T10–T11"; uplift 5%/tháng là số của bản bấm thử.', 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', '2012d142-3054-45cf-b091-ce70fcc1cd5e', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00');
insert into public.phases (brand_id, name, start_month, end_month, objective, uplift_percent_per_month, note, workspace_id, id, created_at, updated_at) values ('c21ebdb3-66d5-4217-97ac-3765023c266c', 'Optimize & Grow', '2027-06', '2027-09', 'Tối ưu và tăng trưởng: tinh chỉnh channel mix theo dữ liệu GĐ2, duy trì nhịp owned publishing.', 5, 'Objective điền tạm cho bản bấm thử; uplift 5%/tháng là số của bản bấm thử.', 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', '1a099357-340e-41f6-bb66-dd3755c3f585', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00');
insert into public.phases (brand_id, name, start_month, end_month, objective, uplift_percent_per_month, note, workspace_id, id, created_at, updated_at) values ('c21ebdb3-66d5-4217-97ac-3765023c266c', 'Scale & Convert', '2027-10', '2027-12', 'Mở rộng và chuyển đổi: dồn lực wave T10–T11, đẩy Signup → First → Paid cuối năm.', 3, 'Objective điền tạm — căn cứ wave T10–T11 trong file nguồn; uplift 3%/tháng là số của bản bấm thử.', 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', 'ec141e9a-0268-4ab4-9993-c181563049bd', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00');
