insert into public.content_pillars (bu_product_id, name, description, classification_guide, status, workspace_id, id, created_at, updated_at) values ('97e4fecf-8f96-4d49-81ae-825d22b8525d', 'Kiến thức ngành', 'Giải thích khái niệm, xu hướng và kiến thức nền của ngành.', 'Phân loại khi bài chủ yếu giúp người đọc hiểu một chủ đề. Ví dụ: giải thích ứng dụng VR trong đào tạo.', 'active', 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6', '95710bbc-8dd9-4738-b26c-6e47d842ea3e', '2026-11-17T12:00:00+07:00', '2026-11-17T12:00:00+07:00');
