-- 4 SỐ NEO:
-- Neo 1 — Lumus 776 content (tổng qty plan_rows của Brand Lumus AI):
select sum(qty) as lumus_content_qty, 776 as ky_vong from public.plan_rows where workspace_id = 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6' and brand_id = 'c21ebdb3-66d5-4217-97ac-3765023c266c';
-- Neo 2 — Tổng ngân sách Planning năm 2027, lọc Brand/Segment = Tất cả:
-- 1.598.700.000đ = Σ (qty × đơn giá hiệu dụng) + Σ budget trực tiếp (Paid),
-- đơn giá hiệu dụng = unit_price của dòng, trống thì benchmark Brand×Channel.
select sum(case when pr.qty is not null then pr.qty * coalesce(pr.unit_price, b.unit_price, 0) else coalesce(pr.budget, 0) end) as tong_ngan_sach_2027, 1598700000 as ky_vong
from public.plan_rows pr
left join public.benchmarks b on b.workspace_id = pr.workspace_id and b.brand_id = pr.brand_id and b.channel = pr.channel
where pr.workspace_id = 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6' and pr.month like '2027-%';
-- Neo 3 — Camp 01 budget = 51.539.000đ (Σ planned_amount budget_lines của Camp 01):
select sum(planned_amount) as camp01_budget, 51539000 as ky_vong from public.budget_lines where workspace_id = 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6' and campaign_id = '30c93f15-420f-4c3f-806c-904286d9751c';
-- Neo 4 — 115 task thuộc Camp 01:
select count(*) as camp01_tasks, 115 as ky_vong from public.tasks where workspace_id = 'a0870eed-cbdc-4fde-a3da-0b09d83d83b6' and campaign_id = '30c93f15-420f-4c3f-806c-904286d9751c';
